void Draw(ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();if(!s.refresh)s.Init();if(s.switch_wallet){auto binding=*s.state.documents.Find(1)->binding;binding.wallet=*WalletId::Make("another existing wallet");const auto second=s.state.documents.OpenWallet("Another wallet",binding,true);s.state.documents.Find(second)->history.enabled=true;s.switch_wallet=false;}
    if(s.enable_explorer){
        auto settings=s.recovery->LoadWorkspacePreferences();
        if(!settings)throw std::runtime_error("fixture preferences unavailable");
        settings.value->preferences.explorer=ExplorerMode::NetworkDefault;
        if(!s.recovery->SaveWorkspacePreferences(*settings.value))throw std::runtime_error("fixture explorer opt-in failed");
        s.state.general.initialized=false;s.enable_explorer=false;
    }
    if(s.protect_lock){s.lock_ok=s.recovery->Protect(s.state.documents,"focus-fixture-password-123") && sh::RequestPrivacyLock(s.state,s);s.protect_lock=false;}if(s.unlock){s.unlock_ok=s.recovery->Unlock("focus-fixture-password-123",s.state.documents);s.unlock=false;}
    if(s.evict){auto binding=*s.state.documents.Find(1)->binding;binding.wallet=*WalletId::Make("another existing wallet");const auto second=s.state.documents.OpenWallet("Another wallet",binding,true);s.state.documents.Find(second)->history.enabled=true;for(uint64_t index=0;index<7;++index){auto cached=binding;cached.wallet=*WalletId::Make("cached-wallet-"+std::to_string(index));const auto id=s.state.documents.OpenWallet("Retained wallet "+std::to_string(index),cached,true);s.state.documents.Find(id)->history.enabled=true;s.state.histories[id]={};}if(!s.state.documents.Activate(second))throw std::runtime_error("activate wallet for cache eviction");s.evict=false;}if(s.refresh_now){s.refresh->RequestNow(0);s.refresh_now=false;}s.refresh->Tick(RefreshMonotonicMs());if(s.probe_ack){const auto view=s.refresh->View();s.ack_denied=view.history && !s.refresh->AcknowledgeHistory(*view.identity,s.refresh->PendingHistorySequence(),view.history->lastblock);s.probe_ack=false;}if(s.offline_toggle){s.refresh->SetOffline(true,0);s.offline_toggle=false;}const auto current=s.refresh->View();s.limited=current.ledger && current.ledger->Limited();s.complete=current.ledger && current.ledger->Complete();s.chain_current=current.chain_current;s.scan_budget=current.scan_budget;if(s.conflict){const auto scope=a::HistoryMetadataScope(*s.state.documents.Find(1)->binding);auto old=s.recovery->HistoryMetadata(scope);s.conflict_done=bool(s.recovery->SaveHistoryLabel(scope,H('1'),"Other writer",old.value->revision));s.conflict=false;}
    ui::components::NativeInputScope native(&s.files);const auto theme=ui::MakeBootstrapTheme({});ui::theme::Scope style(theme);try{s.facts=sh::DrawWorkspace(s.state,s,theme,{},ImVec2{1280,800});}catch(const std::runtime_error& error){if(!s.capture_limit_exception)throw;s.frame_exception=error.what();std::fprintf(stderr,"production action exception: %s\n",error.what());}if(const auto* d=s.state.documents.Find(1);d && d->binding){auto stored=s.recovery->HistoryMetadata(a::HistoryMetadataScope(*d->binding));if(stored){s.stored_revision=stored.value->revision;s.stored_labels.clear();for(const auto& label:stored.value->labels)if(label.target.kind==storage::TargetKind::Transaction)s.stored_labels[label.target.key]=label.text;}}if(const auto* other=s.state.documents.Find(2);other && other->binding){auto stored=s.recovery->HistoryMetadata(a::HistoryMetadataScope(*other->binding));if(stored)s.other_stored_revision=stored.value->revision;}}
ImGuiTest* Test(ImGuiTestEngine* engine,const char* name){auto* t=IM_REGISTER_TEST(engine,"roots.history",name);t->SetVarsDataType<Fixture>();t->GuiFunc=Draw;return t;}
void Ready(ImGuiTestContext* ctx,Fixture& s){ctx->SetRef("###workspace");for(int i=0;i<30 && s.facts.history_order.size()!=2;++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}ctx->Yield(3);}
