    auto* t=Test(engine,"sort_filter_tree_chart_copy_and_readonly_document");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);IM_CHECK_EQ(s.facts.history_order.size(),2);bool owned_cells=false;for(const auto& node:s.state.presentation.Tree().nodes)if(node.name=="Transaction value"){const auto* row=s.state.presentation.Tree().Find(node.parent);const auto* grid=row?s.state.presentation.Tree().Find(row->parent):nullptr;owned_cells|=row && grid && row->role==ui::components::ax::SemanticRole::Row && grid->role==ui::components::ax::SemanticRole::Grid;}IM_CHECK(owned_cells);ctx->ItemNavActivate(s.facts.history.at("sort-1").id);ctx->Yield(3);IM_CHECK_EQ(s.facts.history_order.front(),H('2').hex());ctx->ItemClick(s.facts.history.at("row-"+H('1').hex()).id);ctx->Yield(2);IM_CHECK_EQ(s.state.documents.Find(1)->history.selected,H('1').hex());ctx->ItemNavActivate(s.facts.history.at("chart-next").id);ctx->Yield(3);IM_CHECK_EQ(s.state.documents.Find(1)->history.selected,H('2').hex());ctx->ItemClick(s.facts.history.at("expand-"+H('2').hex()).id);ctx->Yield(2);IM_CHECK(s.state.documents.Find(1)->history.expanded.contains(H('2').hex()));IM_CHECK(s.state.presentation.Snapshot().find("Input")!=std::string::npos);IM_CHECK(s.state.presentation.Snapshot().find("Unknown")!=std::string::npos);ctx->ItemInputValue(s.facts.history.at("filter").id,"Zulu");ctx->Yield(2);IM_CHECK_EQ(s.facts.history_order.size(),1);IM_CHECK_EQ(s.state.documents.Find(1)->history.selected,H('2').hex());ctx->ItemInputValue(s.facts.history.at("filter").id,"");ctx->Yield(2);ctx->ItemNavActivate(s.facts.history.at("copy-value").id);ctx->Yield(2);IM_CHECK_EQ(s.effects.size(),1);IM_CHECK_EQ(std::get<ui::components::CopyAmount>(*s.effects.back().component).value.sats(),200000000);s.refresh_now=true;ctx->Yield(5);IM_CHECK_EQ(s.state.documents.Find(1)->history.selected,H('2').hex());s.state.unit=1;ctx->Yield(2);IM_CHECK(s.state.presentation.Snapshot().find("200000000 sats")!=std::string::npos);ctx->ItemNavActivate(s.facts.history.at("open").id);ctx->Yield(3);IM_CHECK_EQ(s.state.documents.Documents().size(),2);IM_CHECK(s.state.documents.Active()->observed_transaction);IM_CHECK_EQ(s.effects.size(),1);IM_CHECK(s.state.presentation.Tree().Validate());ctx->ItemNavActivate(s.facts.history.at("show-wallet").id);ctx->Yield(2);IM_CHECK_EQ(s.state.documents.ActiveId(),1);};
