    t=Test(engine,"csv_acknowledgement_existing_file_and_privacy_retirement");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);IM_CHECK(!s.facts.history.at("csv").disabled);ctx->ItemClick(s.facts.history.at("csv").id);ctx->Yield(4);std::ifstream file(s.files.destination);const std::string original{std::istreambuf_iterator<char>(file),{}};IM_CHECK(original.find("1.00000001")!=std::string::npos && original.find("3.00000001")!=std::string::npos);IM_CHECK(std::filesystem::status(s.files.destination).permissions()==(std::filesystem::perms::owner_read|std::filesystem::perms::owner_write));ctx->ItemClick(s.facts.history.at("csv").id);ctx->Yield(4);std::ifstream again(s.files.destination);const std::string retained{std::istreambuf_iterator<char>(again),{}};IM_CHECK_EQ(retained,original);IM_CHECK(s.state.histories.at(1).error.find("existing files are retained")!=std::string::npos);s.files.destination=(s.scratch/"retired.csv").string();s.files.hold=true;ctx->ItemClick(s.facts.history.at("csv").id);ctx->Yield(2);IM_CHECK(s.files.active && !s.state.histories.at(1).export_data.empty());s.state.privacy.hidden=true;ctx->Yield(3);IM_CHECK(!s.files.active && s.state.histories.at(1).export_data.empty() && !std::filesystem::exists(s.files.destination));IM_CHECK(s.effects.empty());};

    t=Test(engine,"evicted_label_cache_requires_fresh_metadata_read");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemInputValue(s.facts.history.at("label-"+H('2').hex()).id,"Durable scoped label");ctx->Yield(2);IM_CHECK(s.state.documents.Find(1)->history.metadata_loaded);IM_CHECK_EQ(s.state.histories.at(1).labels.at(H('2').hex()),"Durable scoped label");s.evict=true;ctx->Yield(2);IM_CHECK_EQ(s.state.documents.ActiveId(),2);IM_CHECK(!s.state.histories.contains(1));IM_CHECK(!s.state.documents.Find(1)->history.metadata_loaded);s.state.documents.Activate(1);ctx->Yield(3);IM_CHECK(s.state.documents.Find(1)->history.metadata_loaded);IM_CHECK_EQ(s.state.histories.at(1).labels.at(H('2').hex()),"Durable scoped label");IM_CHECK(s.effects.empty());};

    t=Test(engine,"focus_loss_control_without_enter");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.history.at("label-"+H('2').hex()).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Focus control save");ctx->Yield(2);IM_CHECK_EQ(s.state.documents.Find(1)->history.drafts.at(H('2').hex()).draft,"Focus control save");IM_CHECK_EQ(s.state.documents.Find(1)->history.drafts.at(H('2').hex()).saved,"Alpha");ctx->ItemClick(s.facts.history.at("filter").id);ctx->Yield(3);IM_CHECK(s.stored_labels.contains(H('2').hex()));IM_CHECK_EQ(s.stored_labels.at(H('2').hex()),"Focus control save");IM_CHECK_EQ(s.state.documents.Find(1)->history.drafts.at(H('2').hex()).saved,"Focus control save");IM_CHECK_EQ(s.state.documents.Find(1)->history.metadata_revision,1);};
    t=Test(engine,"focus_loss_row_without_enter");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.history.at("label-"+H('2').hex()).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Focus row save");ctx->Yield(2);IM_CHECK_EQ(s.state.documents.Find(1)->history.drafts.at(H('2').hex()).draft,"Focus row save");ctx->ItemClick(s.facts.history.at("row-"+H('1').hex()).id);ctx->Yield(3);IM_CHECK_EQ(s.state.documents.Find(1)->history.selected,H('1').hex());IM_CHECK(s.stored_labels.contains(H('2').hex()));IM_CHECK_EQ(s.stored_labels.at(H('2').hex()),"Focus row save");IM_CHECK_EQ(s.state.documents.Find(1)->history.drafts.at(H('2').hex()).saved,"Focus row save");IM_CHECK_EQ(s.state.documents.Find(1)->history.metadata_revision,1);};

