    t=Test(engine,"bounded_partial_stale_and_current_chain_states");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);const auto selected=s.state.documents.Find(1)->history.selected;const auto wait=[&](const char* text){for(int i=0;i<40 && s.state.presentation.Snapshot().find(text)==std::string::npos;++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}IM_CHECK(s.state.presentation.Snapshot().find(text)!=std::string::npos);};s.history_phase=1;s.refresh_now=true;wait("Partial scan");IM_CHECK(s.facts.history_order.size()==2 && !s.facts.history.at("scan-earlier").disabled);s.probe_ack=true;ctx->Yield(2);IM_CHECK(s.ack_denied);ctx->ItemNavActivate(s.facts.history.at("scan-earlier").id);for(int i=0;i<40 && !s.complete;++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}IM_CHECK(s.complete && s.scan_budget==512);IM_CHECK_EQ(s.state.documents.Find(1)->history.selected,selected);s.history_phase=2;s.refresh_now=true;wait("Refresh failed");IM_CHECK(s.facts.history_order.size()==2 && !s.chain_current);IM_CHECK(s.state.presentation.Snapshot().find("Current chain state Unknown")!=std::string::npos);IM_CHECK(s.state.presentation.Snapshot().find("2023-11-14")!=std::string::npos);s.history_phase=3;s.refresh_now=true;wait("unconfirmed parent");IM_CHECK(s.effects.empty() && s.explorers.empty() && s.fees.empty());};
